
-- 1. Create admin_users table
CREATE TABLE IF NOT EXISTS public.admin_users (
    email TEXT PRIMARY KEY,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Habilitar RLS para admin_users e garantir que ela pode ser lida
ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Permitir leitura de admin_users" ON public.admin_users;
CREATE POLICY "Permitir leitura de admin_users" ON public.admin_users FOR SELECT USING (true);

-- => ADICIONE SEU EMAIL AQUI ANTES DE RODAR O SCRIPT:

-- 2. Create products table
DROP TABLE IF EXISTS public.products CASCADE;
DROP TABLE IF EXISTS public.categories CASCADE;

CREATE TABLE IF NOT EXISTS public.categories (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS public.products (
    id TEXT PRIMARY KEY,
    category_id TEXT REFERENCES public.categories(id) ON DELETE SET NULL,
    name TEXT NOT NULL,
    description TEXT,
    default_price NUMERIC(10, 2) NOT NULL DEFAULT 0.00,
    pix_price NUMERIC(10, 2),
    monthly_fee NUMERIC(10, 2) DEFAULT 0.00,
    image_url TEXT,
    is_active BOOLEAN DEFAULT true,
    commercial_rules JSONB DEFAULT '{"allow_pix": true, "allow_boleto": true, "allow_card": true, "allow_financing": true, "max_boleto_installments": 3, "max_card_installments": 12}'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 3. Create tecnicos table
CREATE TABLE IF NOT EXISTS public.tecnicos (
    id SERIAL PRIMARY KEY,
    nome TEXT NOT NULL,
    categoria TEXT,
    tipo TEXT,
    descricao TEXT,
    telefone TEXT,
    email TEXT,
    lat DOUBLE PRECISION NOT NULL,
    lng DOUBLE PRECISION NOT NULL,
    vendedor_parceiro TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 4. Enable RLS
ALTER TABLE public.tecnicos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY;

-- 5. Policies
DROP POLICY IF EXISTS "Leitura de tecnicos por todos" ON public.tecnicos;
CREATE POLICY "Leitura de tecnicos por todos" ON public.tecnicos FOR SELECT USING (true);

DROP POLICY IF EXISTS "Leitura de produtos por todos" ON public.products;
CREATE POLICY "Leitura de produtos por todos" ON public.products FOR SELECT USING (true);

DROP POLICY IF EXISTS "Leitura de categorias por todos" ON public.categories;
CREATE POLICY "Leitura de categorias por todos" ON public.categories FOR SELECT USING (true);

DROP POLICY IF EXISTS "Admin full access on products" ON public.products;
CREATE POLICY "Admin full access on products" ON public.products FOR ALL USING (
    EXISTS (SELECT 1 FROM public.admin_users WHERE email = auth.jwt()->>'email')
);

DROP POLICY IF EXISTS "Admin full access on tecnicos" ON public.tecnicos;
CREATE POLICY "Admin full access on tecnicos" ON public.tecnicos FOR ALL USING (
    EXISTS (SELECT 1 FROM public.admin_users WHERE email = auth.jwt()->>'email')
);

-- 6. Insert Initial Tecnicos Data
ON CONFLICT (id) DO NOTHING;
SELECT setval('tecnicos_id_seq', (SELECT COALESCE(MAX(id), 0) + 1 FROM public.tecnicos), false);

-- 7. Insert Initial Categories Data
ON CONFLICT (id) DO NOTHING;

-- 8. Insert Initial Products Data
ON CONFLICT (id) DO NOTHING;
